contract:
{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "createTree",
    "signature": "createTree(parent: List[int], N: int) -> TreeNode"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(parent, list) and all(isinstance(x, int) for x in parent)",
      "description": "parent is a list of integers"
    },
    {
      "id": "P2",
      "expression": "isinstance(N, int) and N >= 1 and N == len(parent)",
      "description": "N is an integer, N is at least 1, and N equals the length of parent"
    },
    {
      "id": "P3",
      "expression": "any(x == -1 for x in parent) and sum(x == -1 for x in parent) == 1",
      "description": "parent contains exactly one -1, indicating the root"
    },
    {
      "id": "P4",
      "expression": "all(-1 <= x < N for x in parent if x != -1)",
      "description": "all parent values are valid node indices or -1"
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "isinstance(return_value, TreeNode) or return_value is None",
      "description": "the return value is a TreeNode or None"
    },
    {
      "id": "Q2",
      "expression": "all(isinstance(node, TreeNode) for node in traverse_tree(return_value))",
      "description": "all nodes in the tree are TreeNode instances"
    },
    {
      "id": "Q3",
      "expression": "count_nodes(return_value) == N",
      "description": "the tree contains exactly N nodes"
    },
    {
      "id": "Q4",
      "expression": "is_root(return_value, parent)",
      "description": "the returned node is the root of the tree as defined by the parent array"
    },
    {
      "id": "Q5",
      "expression": "is_correct_structure(return_value, parent)",
      "description": "the tree structure matches the parent array, with left children appearing before right children"
    }
  ],
  "invariants": []
}

Note: The helper functions `traverse_tree`, `count_nodes`, `is_root`, and `is_correct_structure` are assumed to be defined elsewhere in the codebase and are used here to express the postconditions. These functions are not part of the interface but are necessary to fully specify the postconditions.
